CREATE TABLE IF NOT EXISTS users (created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, user_uuid uuid PRIMARY KEY, google_id VARCHAR(255) NOT NULL, email TEXT NOT NULL);
ALTER TABLE users ADD CONSTRAINT users_email_unique UNIQUE (email);
CREATE TABLE IF NOT EXISTS user_settings (created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, user_uuid uuid PRIMARY KEY, home geography(Point,4326) NOT NULL, remind_timing BIGINT NOT NULL, CONSTRAINT fk_user_settings_user_uuid__user_uuid FOREIGN KEY (user_uuid) REFERENCES users(user_uuid) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS user_calendars (created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, user_calendar_uuid uuid PRIMARY KEY, user_uuid uuid NOT NULL, google_calendar_id TEXT NOT NULL, CONSTRAINT fk_user_calendars_user_uuid__user_uuid FOREIGN KEY (user_uuid) REFERENCES users(user_uuid) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE user_calendars ADD CONSTRAINT user_calendars_user_uuid_google_calendar_id_unique UNIQUE (user_uuid, google_calendar_id);
CREATE TABLE IF NOT EXISTS user_items (created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, user_item_id_uuid uuid NOT NULL, user_uuid uuid NOT NULL, item_type TEXT NOT NULL, item_count INT NOT NULL, CONSTRAINT fk_user_items_user_uuid__user_uuid FOREIGN KEY (user_uuid) REFERENCES users(user_uuid) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE user_items ADD CONSTRAINT user_items_user_uuid_item_type_unique UNIQUE (user_uuid, item_type);
CREATE TABLE IF NOT EXISTS user_subscriptions (created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, user_uuid uuid PRIMARY KEY, plan_name TEXT NOT NULL, status TEXT NOT NULL, expires_at TIMESTAMP NOT NULL, rc_original_transaction_id TEXT NOT NULL, CONSTRAINT fk_user_subscriptions_user_uuid__user_uuid FOREIGN KEY (user_uuid) REFERENCES users(user_uuid) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS user_devices (created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, device_uuid uuid PRIMARY KEY, user_uuid uuid NOT NULL, fcm_token TEXT NOT NULL, CONSTRAINT fk_user_devices_user_uuid__user_uuid FOREIGN KEY (user_uuid) REFERENCES users(user_uuid) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE user_devices ADD CONSTRAINT user_devices_fcm_token_unique UNIQUE (fcm_token);
